texts.en:
Thank you for your order #{id}.

Total: AED {total} ({payment})
Delivery to: {address}, {emirate}

See your order: {link}

texts.ar:
شكراً لطلبك رقم {id}.

الإجمالي: {total} درهم ({payment})
التوصيل إلى: {address}، {emirate}

تفاصيل الطلب: {link}

templates.home:
{{template "top" .}}<h1 style="margin:8px 0 0">{{.storeName}}</h1>{{with .tagline}}<p class="muted">{{.}}</p>{{end}}
<div class="chips"><a class="chip{{if not .category}} on{{end}}" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.all}}</a>{{range .categories}}<a class="chip{{if eq . $.category}} on{{end}}" href="/?c={{.}}{{if eq $.lang "ar"}}&lang=ar{{end}}">{{.}}</a>{{end}}</div>
<div class="grid">{{range .products}}<a class="card" href="/p/{{.id}}{{if eq $.lang "ar"}}?lang=ar{{end}}"><div class="img">{{if .image}}<img src="{{.image}}?w=480" alt="{{.name}}" loading="lazy">{{else}}{{.name}}{{end}}</div>
<div class="body"><div>{{.name}}</div><div class="price">{{if .from}}{{$.t.from}} {{end}}AED {{.price}}</div>{{if le .stock 0}}<div class="muted">{{$.t.out_of_stock}}</div>{{end}}</div></a>{{end}}</div>
{{template "bottom" .}}

templates.product:
{{template "top" .}}{{with .product}}<div class="product"><div class="photo">{{if .image}}<img src="{{.image}}?w=960" alt="{{.name}}">{{else}}{{.name}}{{end}}</div>
<div><h1 style="margin-top:0">{{.name}}</h1><p class="price" style="font-size:22px">AED <span id="price">{{.price}}</span></p><p class="muted">{{$.t.vat_included}}</p><p>{{.description}}</p>
{{if gt .stock 0}}{{with $.variants}}<label for="variant">{{$.t.option}}</label><select id="variant">{{range .}}<option value="{{.id}}"{{if le .stock 0}} disabled{{end}}>{{.name}}{{if le .stock 0}} · {{$.t.out_of_stock}}{{end}}</option>{{end}}</select>{{end}}
<div class="qty"><label for="qty" style="margin:0">{{$.t.quantity}}</label><input id="qty" type="number" min="1" max="{{.stock}}" value="1"></div>
<p><button id="add" data-id="{{.id}}" data-max="{{.stock}}">{{$.t.add_to_cart}}</button> <span id="added" class="ok" hidden>{{$.t.added}}</span></p>
{{else}}<p class="error">{{$.t.out_of_stock}}</p>{{end}}</div></div>{{end}}
<script>
var vs={{.variantsJSON}};vs=vs?JSON.parse(vs):[];var sel=document.getElementById('variant'),b=document.getElementById('add');
function pick(){if(!sel)return null;var v=null;vs.forEach(function(x){if(x.id===Number(sel.value))v=x});return v}
function show(){var v=pick();if(!v)return;document.getElementById('price').textContent=v.price;b.dataset.max=v.stock;document.getElementById('qty').max=v.stock}
if(sel){for(var i=0;i<sel.options.length;i++){if(!sel.options[i].disabled){sel.selectedIndex=i;break}}sel.addEventListener('change',show);show()}
if(b){b.addEventListener('click',function(){var id=Number(b.dataset.id),max=Number(b.dataset.max),v=pick(),vid=v?v.id:0;
var q=Math.max(1,Math.min(max,Math.floor(Number(document.getElementById('qty').value)||1)));var c=rxCart(),f=null;
c.forEach(function(i){if(i.id===id&&(i.v||0)===vid)f=i});if(f){f.qty=Math.min(max,f.qty+q)}else{var it={id:id,qty:q};if(vid)it.v=vid;c.push(it)}
rxSave(c);document.getElementById('added').hidden=false})}
</script>{{template "bottom" .}}

templates.cart:
{{template "top" .}}<h1>{{.t.cart}}</h1>{{with .error}}<p class="error">{{.}}</p>{{end}}
<div id="empty" class="panel" hidden><p>{{.t.empty_cart}}</p><a class="btn" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.continue_shopping}}</a></div>
<div id="full" hidden><div class="panel" id="lines"></div>
<div class="panel"><div class="row"><span>{{.t.subtotal}}</span><span>AED <span id="subtotal"></span></span></div>
<div class="row"><span>{{.t.delivery}}</span><span id="delivery"></span></div><div class="row total"><span>{{.t.total}}</span><span>AED <span id="total"></span></span></div>
<p class="muted">{{.t.vat_included}} · {{.t.free_delivery_over}} AED {{.store.free_delivery_over}}</p></div>
<form class="panel" method="post" action="/checkout"><h2 style="margin-top:0">{{.t.checkout}}</h2>
<input type="hidden" name="cart" id="cart-field"><input type="hidden" name="lang" value="{{.lang}}">
{{if not .user}}<p><a class="btn" href="/_rx/auth/login?next=/cart{{if eq .lang "ar"}}%3Flang%3Dar{{end}}">{{.t.sign_in_to_checkout}}</a></p>{{else}}
<label for="name">{{.t.name}}</label><input id="name" name="name" autocomplete="name" required value="{{.user.name}}">
<label for="phone">{{.t.phone}}</label><input id="phone" name="phone" type="tel" autocomplete="tel" required value="{{.user.phone}}">
<label for="address">{{.t.address}}</label><textarea id="address" name="address" rows="2" autocomplete="street-address" required></textarea>
<label for="emirate">{{.t.emirate}}</label><select id="emirate" name="emirate" required><option>Dubai</option><option>Abu Dhabi</option><option>Sharjah</option><option>Ajman</option><option>Umm Al Quwain</option><option>Ras Al Khaimah</option><option>Fujairah</option></select>
<label for="coupon">{{.t.coupon}}</label><input id="coupon" name="coupon" autocomplete="off" style="text-transform:uppercase">
<label>{{.t.payment}}</label>{{if .store.card_enabled}}<label style="display:flex;gap:8px;margin:6px 0"><input type="radio" name="payment" value="card" checked style="width:auto"> {{.t.pay_card}}</label>{{end}}
{{if .store.cod_enabled}}<label style="display:flex;gap:8px;margin:6px 0"><input type="radio" name="payment" value="cod"{{if not .store.card_enabled}} checked{{end}} style="width:auto"> {{.t.pay_cod}}</label>{{end}}
<p><button>{{.t.place_order}}</button></p>{{end}}</form></div>
<script>
(function(){var c=rxCart();if(!c.length){document.getElementById('empty').hidden=false;return}
function key(i){return i.v?i.id+'.'+i.v:String(i.id)}
fetch('/api/products?ids='+c.map(key).join(',')+'&lang={{.lang}}').then(function(r){return r.json()}).then(function(d){
var by={};d.products.forEach(function(p){by[p.key]=p});c=c.filter(function(i){return by[key(i)]&&by[key(i)].stock>0});
c.forEach(function(i){i.qty=Math.min(i.qty,by[key(i)].stock)});rxSave(c);if(!c.length){document.getElementById('empty').hidden=false;return}
var box=document.getElementById('lines');box.textContent='';var sub=0;
c.forEach(function(i){var p=by[key(i)];sub+=p.priceNum*i.qty;var row=document.createElement('div');row.className='row';
var left=document.createElement('span');left.textContent=p.name+' × '+i.qty;var right=document.createElement('span');right.textContent='AED '+(p.priceNum*i.qty).toFixed(2)+' ';
var rm=document.createElement('button');rm.className='secondary';rm.style.padding='2px 8px';rm.textContent='{{.t.remove}}';
rm.onclick=function(){rxSave(rxCart().filter(function(x){return key(x)!==key(i)}));location.reload()};right.appendChild(rm);row.appendChild(left);row.appendChild(right);box.appendChild(row)});
var del=sub>=d.free_delivery_over?0:d.delivery_fee;document.getElementById('subtotal').textContent=sub.toFixed(2);
document.getElementById('delivery').textContent=del?'AED '+del.toFixed(2):'{{.t.free}}';document.getElementById('total').textContent=(sub+del).toFixed(2);
document.getElementById('cart-field').value=JSON.stringify(c);document.getElementById('full').hidden=false})})();
</script>{{template "bottom" .}}

templates.order:
{{template "top" .}}{{with .order}}{{if $.placed}}<p class="ok" style="font-size:18px">{{$.t.thank_you}}</p><script>try{localStorage.removeItem('cart')}catch(e){}</script>{{end}}
<h1>{{$.t.order}} #{{.id}}</h1><p>{{$.t.status}}: <strong>{{.statusText}}</strong></p>
{{if eq .status "pending"}}<form method="post" action="/orders/{{.id}}/pay"><input type="hidden" name="lang" value="{{$.lang}}"><button>{{$.t.pay_now}}</button></form>{{end}}
<div class="panel">{{range .lines}}<div class="row"><span>{{.name}} × {{.qty}}</span><span>AED {{.line}}</span></div>{{end}}
{{if .discount}}<div class="row"><span>{{$.t.discount}} ({{.coupon}})</span><span>− AED {{.discount}}</span></div>{{end}}
<div class="row"><span>{{$.t.delivery}}</span><span>{{if .delivery}}AED {{.delivery}}{{else}}{{$.t.free}}{{end}}</span></div>
<div class="row total"><span>{{$.t.total}}</span><span>AED {{.total}}</span></div><p class="muted">{{$.t.vat_included}}: AED {{.vat}}</p>{{if ne .status "pending"}}<p><a href="/orders/{{.id}}/invoice{{if eq $.lang "ar"}}?lang=ar{{end}}">{{$.t.view_invoice}}</a></p>{{end}}</div>
<div class="panel"><p>{{.name}} · {{.phone}}</p><p class="muted">{{.address}}, {{.emirate}}</p><p class="muted">{{if eq .method "cod"}}{{$.t.pay_cod}}{{else}}{{$.t.pay_card}}{{end}}</p></div>{{end}}
{{template "bottom" .}}

scripts.home:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function store() { return db.query('SELECT * FROM store ORDER BY id LIMIT 1')[0]; }
function money(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function page(req, extra) {
  const lang = langOf(req);
  const s = store();
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: texts(lang), user: req.user,
    store: s, storeName: lang === 'ar' && s.name_ar ? s.name_ar : s.name, tagline: lang === 'ar' && s.tagline_ar ? s.tagline_ar : s.tagline,
    path: req.path, wa: (s.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}
// Emails the buyer a confirmation in the order's language, and is quiet on failure.
function confirmOrder(o, link) {
  if (!o.email) return;
  const lang = o.lang === 'ar' ? 'ar' : 'en', t = texts(lang);
  const fill = (s) => s.replace(/\{id\}/g, o.id).replace(/\{store\}/g, lang === 'ar' && store().name_ar ? store().name_ar : store().name)
    .replace(/\{total\}/g, money(o.total)).replace(/\{payment\}/g, o.payment_method === 'cod' ? t.pay_cod : t.pay_card)
    .replace(/\{address\}/g, o.address).replace(/\{emirate\}/g, o.emirate).replace(/\{link\}/g, link);
  try { email.send({to: o.email, subject: fill(t.email_subject), text: fill(t.email_body)}); } catch (e) { console.warn('confirmation not sent: ' + e); }
}
// vs is variantSummary(): products with variants show the lowest price and the stock of all their variants.
function localize(p, lang, vs) {
  const v = vs && vs[p.id];
  const price = v ? v.min_price : p.price;
  return {id: p.id, name: lang === 'ar' && p.name_ar ? p.name_ar : p.name, description: lang === 'ar' && p.description_ar ? p.description_ar : p.description,
    category: p.category, price: money(price), priceNum: price, image: p.image, stock: v ? v.stock : p.stock,
    hasVariants: !!v, from: !!v && v.min_price !== v.max_price};
}
function variantSummary() {
  const m = {};
  for (const r of db.query(`SELECT v.product_id, SUM(v.stock) AS stock, MIN(coalesce(v.price, p.price)) AS min_price, MAX(coalesce(v.price, p.price)) AS max_price
    FROM variants v JOIN products p ON p.id = v.product_id WHERE v.active = 1 GROUP BY v.product_id`)) m[r.product_id] = r;
  return m;
}
function variantsOf(p, lang) {
  return db.query('SELECT * FROM variants WHERE product_id = ? AND active = 1 ORDER BY id', p.id).map(v => {
    const price = v.price === null ? p.price : v.price;
    return {id: v.id, name: lang === 'ar' && v.name_ar ? v.name_ar : v.name, price: money(price), priceNum: price, stock: v.stock};
  });
}
// Takes stock (sign -1) or gives it back (sign 1) for order lines; lines with v are variants.
function restock(lines, sign) {
  for (const l of lines) {
    if (l.v) db.exec('UPDATE variants SET stock = stock + ? WHERE id = ?', sign * l.qty, l.v);
    else db.exec('UPDATE products SET stock = stock + ? WHERE id = ?', sign * l.qty, l.id);
  }
}

// GET /?c=Category&lang=ar
function handle(req) {
  const lang = langOf(req);
  const c = req.query.c || '';
  const rows = c ? db.query('SELECT * FROM products WHERE active = 1 AND category = ? ORDER BY id', c)
                 : db.query('SELECT * FROM products WHERE active = 1 ORDER BY id');
  const vs = variantSummary();
  const cats = db.query('SELECT DISTINCT category FROM products WHERE active = 1 AND category IS NOT NULL AND category != \'\' ORDER BY category');
  return {template: 'home', data: page(req, {products: rows.map(p => localize(p, lang, vs)), categories: cats.map(r => r.category), category: c})};
}

