scripts.daily_report:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function store() { return db.query('SELECT * FROM store ORDER BY id LIMIT 1')[0]; }
function money(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function page(req, extra) {
  const lang = langOf(req);
  const s = store();
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: texts(lang), user: req.user,
    store: s, storeName: lang === 'ar' && s.name_ar ? s.name_ar : s.name, tagline: lang === 'ar' && s.tagline_ar ? s.tagline_ar : s.tagline,
    path: req.path, wa: (s.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}
// Emails the buyer a confirmation in the order's language, and is quiet on failure.
function confirmOrder(o, link) {
  if (!o.email) return;
  const lang = o.lang === 'ar' ? 'ar' : 'en', t = texts(lang);
  const fill = (s) => s.replace(/\{id\}/g, o.id).replace(/\{store\}/g, lang === 'ar' && store().name_ar ? store().name_ar : store().name)
    .replace(/\{total\}/g, money(o.total)).replace(/\{payment\}/g, o.payment_method === 'cod' ? t.pay_cod : t.pay_card)
    .replace(/\{address\}/g, o.address).replace(/\{emirate\}/g, o.emirate).replace(/\{link\}/g, link);
  try { email.send({to: o.email, subject: fill(t.email_subject), text: fill(t.email_body)}); } catch (e) { console.warn('confirmation not sent: ' + e); }
}
// vs is variantSummary(): products with variants show the lowest price and the stock of all their variants.
function localize(p, lang, vs) {
  const v = vs && vs[p.id];
  const price = v ? v.min_price : p.price;
  return {id: p.id, name: lang === 'ar' && p.name_ar ? p.name_ar : p.name, description: lang === 'ar' && p.description_ar ? p.description_ar : p.description,
    category: p.category, price: money(price), priceNum: price, image: p.image, stock: v ? v.stock : p.stock,
    hasVariants: !!v, from: !!v && v.min_price !== v.max_price};
}
function variantSummary() {
  const m = {};
  for (const r of db.query(`SELECT v.product_id, SUM(v.stock) AS stock, MIN(coalesce(v.price, p.price)) AS min_price, MAX(coalesce(v.price, p.price)) AS max_price
    FROM variants v JOIN products p ON p.id = v.product_id WHERE v.active = 1 GROUP BY v.product_id`)) m[r.product_id] = r;
  return m;
}
function variantsOf(p, lang) {
  return db.query('SELECT * FROM variants WHERE product_id = ? AND active = 1 ORDER BY id', p.id).map(v => {
    const price = v.price === null ? p.price : v.price;
    return {id: v.id, name: lang === 'ar' && v.name_ar ? v.name_ar : v.name, price: money(price), priceNum: price, stock: v.stock};
  });
}
// Takes stock (sign -1) or gives it back (sign 1) for order lines; lines with v are variants.
function restock(lines, sign) {
  for (const l of lines) {
    if (l.v) db.exec('UPDATE variants SET stock = stock + ? WHERE id = ?', sign * l.qty, l.v);
    else db.exec('UPDATE products SET stock = stock + ? WHERE id = ?', sign * l.qty, l.id);
  }
}

// GET /p/:id
// Job: every evening, email (and WhatsApp, if turned on) the owner a summary of today's orders.
// created_at is UTC; the day is counted from midnight in Dubai (UTC+4).
function handle(req) {
  const dubai = new Date(Date.now() + 4 * 3600 * 1000);
  const midnight = Date.UTC(dubai.getUTCFullYear(), dubai.getUTCMonth(), dubai.getUTCDate()) - 4 * 3600 * 1000;
  const since = new Date(midnight).toISOString().replace('T', ' ').slice(0, 19);
  const rows = db.query(`SELECT status, payment_method, COUNT(*) AS n, SUM(total) AS total FROM orders WHERE created_at >= ? GROUP BY status, payment_method`, since);
  if (rows.length === 0) return {text: 'no orders today'};
  let count = 0, sum = 0;
  const lines = rows.map(r => {
    count += r.n;
    if (r.status === 'paid' || r.status === 'cod' || r.status === 'shipped' || r.status === 'delivered') sum += r.total;
    return r.n + ' x ' + r.status + ' (' + r.payment_method + '): AED ' + money(r.total);
  });
  const low = db.query('SELECT name, stock FROM products WHERE active = 1 AND stock <= 3 ORDER BY stock LIMIT 10');
  let text = lines.join('\n');
  if (low.length) text += '\n\nLow stock:\n' + low.map(p => p.name + ': ' + p.stock).join('\n');
  notify.owner({subject: 'Today: ' + count + ' order' + (count === 1 ? '' : 's') + ', AED ' + money(sum) + ' paid or cash on delivery', text: text});
  return {text: count + ' orders reported'};
}
